-- Archive script bindings, disables and conditions rejected for spells absent on build 70888.
START TRANSACTION;
CREATE TEMPORARY TABLE absent_spell_bindings (spell_id INT NOT NULL, ScriptName VARCHAR(64) COLLATE utf8mb4_unicode_ci NOT NULL, PRIMARY KEY (spell_id,ScriptName)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DELETE d FROM spell_script_names d JOIN absent_spell_bindings b ON b.spell_id=d.spell_id AND b.ScriptName=d.ScriptName;
